import numpy as np, sys
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt

def load(f):
    lines=open(f).read().splitlines(); n=int(lines[0]); els=[]; pos=[]
    for ln in lines[2:2+n]:
        p=ln.split(); els.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return els,np.array(pos)

els,pos=load('optimized.xyz'); n=len(els)
radii={'H':0.31,'C':0.76,'P':1.07,'Ir':1.37}
bonds=[]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(pos[i]-pos[j])
        if d < radii[els[i]]+radii[els[j]]+0.45: bonds.append((i,j))

# Frame: e_z(vertical) = Ir->Cp centroid. e_x: P-Ir projected.
cpc=pos[3:8].mean(axis=0); e_z=cpc-pos[0]; e_z/=np.linalg.norm(e_z)
pv=pos[2]-pos[0]; pv=pv-np.dot(pv,e_z)*e_z; pv/=np.linalg.norm(pv)
e_x=-pv  # P to the left
e_y=np.cross(e_z,e_x)
R=np.stack([e_x,e_z,e_y])   # screen x = e_x, screen y = e_z (vertical), depth = e_y
pr=(R@pos.T).T

colors={'C':'#444444','H':'#c8c8c8','P':'#f39c12','Ir':'#17518c'}
sizes={'C':120,'H':22,'P':320,'Ir':450}
fig,ax=plt.subplots(figsize=(9,8),dpi=130)
# sort by depth for pseudo-3d
order=np.argsort(pr[:,2])
for (i,j) in bonds:
    lw=2.0 if (els[i]!='H' and els[j]!='H') else 0.7
    ax.plot([pr[i,0],pr[j,0]],[pr[i,1],pr[j,1]],color='#999999',lw=lw,zorder=1)
for k in (45,46):
    ax.plot([pr[0,0],pr[k,0]],[pr[0,1],pr[k,1]],'r--',lw=1.3,zorder=2)
for i in order:
    ax.scatter(pr[i,0],pr[i,1],c=colors[els[i]],s=sizes[els[i]],edgecolors='k',linewidths=0.4,zorder=3)
ax.set_aspect('equal'); ax.axis('off')
mx=np.abs(pr[:,:2]).max()*1.05
ax.set_xlim(-mx,mx); ax.set_ylim(-mx,mx)
plt.tight_layout(); plt.savefig('render_side.png',bbox_inches='tight')
print("saved render_side.png")
